import { Data, Effect } from 'effect'

import type { FhirResource } from '../resources/index.ts'
import { FhirR4ResourcesHttpApiClient } from './fhir-r4-resources-http-api-client.ts'

/**
 * Raised by {@link upsertResource}'s exhaustive-default arm for a `resourceType`
 * outside the {@link FhirResource} union — reachable only through an untyped
 * path. It is a distinct, tagged failure (not a bare `Error`) so a caller's
 * retry policy can recognise it as *permanent* and skip the backoff: no number
 * of retries turns an unknown resource type into a supported one.
 */
class UnsupportedFhirResourceTypeError extends Data.TaggedError(
  'UnsupportedFhirResourceTypeError'
)<{
  readonly resourceType: string
}> {}

/**
 * Route one parsed {@link FhirResource} to its typed client endpoint — the
 * single `switch (resource.resourceType)` over the FHIR write surface. It
 * lives here, next to the client whose groups it dispatches to, so every
 * caller that writes FHIR reuses one exhaustive dispatch instead of copying
 * it.
 *
 * The write requirement {@link FhirR4ResourcesHttpApiClient} bubbles up as the
 * caller's `R`; app wiring provides the client layer.
 *
 * A `null` logical id is skipped defensively (a typed `Update` path needs a
 * non-null id): a resource whose entities already filtered ids can still reach
 * an untyped path, and a skip is not a failure — it resolves cleanly. The
 * caller owns everything *around* the write (batching, retries, spans, failure
 * accounting); this owns only "which resource type goes to which endpoint".
 *
 * The exhaustive-default arm `fail`s (with {@link UnsupportedFhirResourceTypeError})
 * on the `unknown` error channel rather than dying: an unrecognized `resourceType`
 * can only arrive through an untyped path, and a *failure* is caught by the
 * caller's `matchEffect` and recorded as one `PersistFailure`, whereas a *defect*
 * would escape that seam and crash the whole batch/run — breaking the sink's
 * "one bad resource can't fail the run" contract (the same contract the null-id
 * skip honours). The failure is tagged so the caller can also tell it apart from
 * a transient write error and skip retrying a permanent one.
 */
const upsertResource = (
  resource: FhirResource
): Effect.Effect<void, unknown, FhirR4ResourcesHttpApiClient> =>
  Effect.gen(function* () {
    if (resource.id === null) {
      yield* Effect.logWarning(`fhir-r4 upsert: skipping ${resource.resourceType} with null id`)
      return
    }
    const client = yield* FhirR4ResourcesHttpApiClient
    const id = resource.id
    const path = { id }
    switch (resource.resourceType) {
      case 'Patient':
        yield* client.Patient.Update({ path, payload: { ...resource, id } })
        break
      case 'Observation':
        yield* client.Observation.Update({ path, payload: { ...resource, id } })
        break
      case 'Binary':
        yield* client.Binary.Update({ path, payload: { ...resource, id } })
        break
      case 'MedicationRequest':
        yield* client.MedicationRequest.Update({ path, payload: { ...resource, id } })
        break
      case 'MedicationDispense':
        yield* client.MedicationDispense.Update({ path, payload: { ...resource, id } })
        break
      case 'DocumentReference':
        yield* client.DocumentReference.Update({ path, payload: { ...resource, id } })
        break
      case 'DiagnosticReport':
        yield* client.DiagnosticReport.Update({ path, payload: { ...resource, id } })
        break
      case 'Practitioner':
        yield* client.Practitioner.Update({ path, payload: { ...resource, id } })
        break
      case 'ServiceRequest':
        yield* client.ServiceRequest.Update({ path, payload: { ...resource, id } })
        break
      case 'ImagingStudy':
        yield* client.ImagingStudy.Update({ path, payload: { ...resource, id } })
        break
      case 'CarePlan':
        yield* client.CarePlan.Update({ path, payload: { ...resource, id } })
        break
      case 'Goal':
        yield* client.Goal.Update({ path, payload: { ...resource, id } })
        break
      case 'PlanDefinition':
        yield* client.PlanDefinition.Update({ path, payload: { ...resource, id } })
        break
      case 'Procedure':
        yield* client.Procedure.Update({ path, payload: { ...resource, id } })
        break
      default: {
        const unreachable: never = resource
        yield* Effect.fail(
          new UnsupportedFhirResourceTypeError({ resourceType: String(unreachable) })
        )
      }
    }
  }).pipe(Effect.asVoid)

export { upsertResource, UnsupportedFhirResourceTypeError }
